import React, { useEffect, useState } from 'react';
import { Button, StatusBadge, PanelHeading, Kpis, MetricCard, Pill, Sq, Empty, Notice, DataTable, PageTools, BarChart, Bar, UiIcon, Switch } from './ui';
import { ContextMenu } from './context-menu';
import { native, cents } from './bridge';
import { CountDialog, VariancePanel, levelsForm, lowStock, type Dialog } from './backoffice';
import { ClosingsPanel, AbcPanel } from './loyalty';
import { simOn, liveOn, activeOn, platformCards, CallBanner, simulateCall, simulatePlatformOrder } from './integrations';
type Row = { id: string;[key: string]: any };
type Props = { page: string; state: any; form: any; action: (type: string, payload: any) => Promise<any>; run: any; openVisit: (id: string) => void; dialog?: Dialog; confirm?: (title: string, description: string, fn: () => Promise<any>, word?: string) => void };
const money = (n: number) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format((n || 0) / 100);
const date = (s: string) => s ? new Date(s).toLocaleString('es-MX', { dateStyle: 'medium', timeStyle: 'short' }) : '—';
const clock = (s: string) => s ? new Date(s).toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', hour12: false }) : '—';
const isToday = (s: string) => !!s && new Date(s).toDateString() === new Date().toDateString();
const field = (key: string, label: string, type = 'text', value: any = '', options?: any[]) => ({ key, label, type, value, options, required: !['checkbox', 'textarea'].includes(type), ...(type === 'number' ? { step: 'any' } : {}) });
const choice = (values: string[]) => values.map(value => ({ value, label: value }));
const flag = (key: string, label: string, value = false) => field(key, label, 'checkbox', value);
const plural = (n: number, one: string, many: string) => n + ' ' + (n === 1 ? one : many);
const num = (v: number, d = 2) => v.toLocaleString('es-MX', { minimumFractionDigits: 0, maximumFractionDigits: d });
// Stock quantities are stored in thousandths of the ingredient's base unit.
function qty(raw: number, unit = 'g') { const v = (raw || 0) / 1000; if (unit === 'g' && Math.abs(v) >= 1000) return num(v / 1000) + ' kg'; if (unit === 'ml' && Math.abs(v) >= 1000) return num(v / 1000) + ' l'; return num(v) + ' ' + (unit === 'unit' ? 'u' : unit); }
function MenuItem({ title, note, icon, onClick }: { title: string; note?: string; icon: string; onClick: () => void }) { return <Button type="button" icon={icon} aria-label={title} onClick={onClick}><span className="mi-t"><b>{title}</b>{note && <small>{note}</small>}</span></Button>; }

export function AccountExtras({ current: v, state: s, form, action, run }: Omit<Props, 'page' | 'openVisit'> & { current: Row }) {

    const id = { id: v.id }, manager = s.user.role === 'manager', folios = (s.folios || []).filter((f: Row) => f.visitId === v.id && !f.void);
    return <>{v.status === 'closed' && manager ? <Button className="ghost" icon="refresh" onClick={() => form('Reabrir cuenta sin revertir stock ni pagos', [field('reason', 'Motivo')], 'visit.reopen', id)}>Reabrir cuenta</Button> : v.status === 'open' && <>
        <Button className="ghost" icon="print" onClick={() => run(() => action('visit.issueBill', id))}>{v.printed ? 'Cuenta emitida · bloqueada' : 'Emitir cuenta'}</Button>
        {v.printed && manager && <Button className="ghost" icon="shield" onClick={() => form('Reapertura autorizada de cuenta impresa', [field('reason', 'Motivo')], 'visit.unlock', id)}>Autorizar reapertura</Button>}
        <Button className="ghost" icon="split" onClick={() => form('Repartir en partes iguales', [field('parts', 'Número de partes', 'number', 2)], 'visit.divide', id)}>Dividir en N partes</Button>
        <Button className="ghost" icon="users" onClick={() => form('Separar por asiento', [field('person', 'Persona / asiento', 'number', 1)], 'visit.split.person', id)}>Dividir por persona</Button>
        <Button className="ghost" icon="star" onClick={() => form('Cortesía con autorización', [field('reason', 'Motivo')], 'request.create', { visitId: v.id, type: 'comp' })}>Solicitar cortesía</Button>
    </>}{folios.length > 0 && <span className="folio-chips">{folios.map((f: Row) => <Pill tone="amber" key={f.id}>Parte {f.number}: {money(f.total)}</Pill>)}</span>}</>;

}

export function Ecosystem({ page, state: s, form, action, run, openVisit, dialog, confirm }: Props) {

    const [result, setResult] = useState<any>(null), [warehouse, setWarehouse] = useState('all');
    const list = (kind: string): Row[] => s[kind + 's'] || [], options = (kind: string, predicate = (x: Row) => true) => list(kind).filter(predicate).map(x => ({ value: x.id, label: x.name || x.id.slice(0, 12) }));
    const select = (key: string, label: string, kind: string, predicate = (x: Row) => true) => field(key, label, 'select', '', options(kind, predicate));
    const name = (kind: string, id: string) => list(kind).find(x => x.id === id)?.name || id || 'Servicio rápido';
    const cash = list('cash').find(c => c.status === 'open'), manager = s.user.role === 'manager';
    const invoke = (type: string, payload: any) => run(async () => setResult(await action(type, payload)));
    const moneyField = (key: string, label: string, value = 0) => ({ ...field(key, label, 'money', value || ''), min: 0 });
    const unit = field('unit', 'Unidad', 'select', 'base', choice(['base', 'kg', 'g', 'mg', 'l', 'ml', 'unit', 'dozen']));
    const stockForm = (type: string) => form(type === 'stock.receive' ? 'Entrada con costo total' : 'Merma de inventario', [select('warehouseId', 'Almacén', 'warehouse'), select('ingredientId', 'Insumo', 'ingredient'), field('quantity', 'Cantidad', 'number', 1), unit, type === 'stock.receive' ? moneyField('cost', 'Costo total MXN') : field('reason', 'Motivo'), field('reference', 'Referencia')], type, {}, undefined, (p: any) => ({ ...p, ...(type === 'stock.receive' ? { cost: cents(p.cost) } : {}) }));
    const recipe = (r?: Row) => form('Receta · nueva versión histórica', [field('name', 'Nombre', 'text', r?.name || ''), field('yield', 'Rendimiento en porciones', 'number', 1), { key: 'linesText', label: 'Insumos de la receta', type: 'rows', value: '', hint: 'Para una subreceta la cantidad son porciones.', rows: { columns: [{ key: 'item', label: 'Insumo', type: 'select' as const, options: [...list('ingredient').map(i => ({ value: i.name, label: i.name })), ...list('recipe').filter(x => x.id !== r?.id).map(x => ({ value: '@' + x.name, label: 'Subreceta · ' + x.name }))] }, { key: 'quantity', label: 'Cantidad', type: 'number' as const, width: '120px', placeholder: '0' }, { key: 'unit', label: 'Unidad', type: 'select' as const, width: '130px', options: choice(['g', 'kg', 'mg', 'ml', 'l', 'unit', 'dozen']) }], split: (l: string) => l.split('|').map(x => x.trim()), join: (c: string[]) => c.join(' | '), add: 'Agregar insumo', empty: 'Agrega los insumos que consume una porción.' } }], 'recipe.save', r ? { id: r.id } : {}, undefined, (p: any) => { const lines = String(p.linesText).split('\n').filter(Boolean).map(line => { const [label, quantity, unit, ...extra] = line.split('|').map(x => x.trim()); if (!label || !quantity || !unit || extra.length) throw new Error('Cada renglón requiere Nombre | cantidad | unidad'); const sub = label.startsWith('@'), matches = list(sub ? 'recipe' : 'ingredient').filter(x => x.name === (sub ? label.slice(1) : label)); if (matches.length !== 1) throw new Error('Nombre inexistente o ambiguo: ' + label); return { [sub ? 'recipeId' : 'ingredientId']: matches[0].id, quantity, unit }; }); return { name: p.name, yield: p.yield, lines }; });

    if (page === 'inventory') {

        const stocks = list('stock'), unitOf = (id: string) => list('ingredient').find(i => i.id === id)?.unit || 'g';
        const shown = stocks.filter(x => warehouse === 'all' || x.warehouseId === warehouse);
        const transfers = list('transfer').filter(t => t.status === 'sender-approved'), jobs = list('stockjob');
        const moves = list('stockmovement').slice().sort((a, b) => Date.parse(b.at) - Date.parse(a.at)).slice(0, 3);
        const low = lowStock(s), lowIds = new Set(low.map(i => i.id));
        const moveLook: Record<string, [string, string, string]> = { receive: ['plus', 'green', 'Entrada'], receipt: ['plus', 'green', 'Entrada'], purchase: ['truck', 'green', 'Compra'], 'count-shortage': ['minus', 'red', 'Faltante de conteo'], 'count-surplus': ['plus', 'green', 'Sobrante de conteo'], 'prepared-waste': ['minus', 'red', 'Merma preparada'], 'transfer-in': ['swap', 'purple', 'Traspaso recibido'], 'transfer-out': ['swap', 'purple', 'Traspaso enviado'], waste: ['minus', 'red', 'Merma'], sale: ['receipt', 'blue', 'Consumo'], return: ['refresh', 'purple', 'Devolución'], transfer: ['swap', 'purple', 'Traspaso'] };
        return <>
            <PageTools><ContextMenu label="Configurar inventario" text="Configurar" icon="settings">
                <MenuItem title="Almacén" note="Nuevo almacén y método de costo" icon="box" onClick={() => form('Almacén', [field('name', 'Nombre'), field('costMethod', 'Método de costo', 'select', 'average', [{ value: 'average', label: 'Promedio ponderado' }, { value: 'fifo', label: 'PEPS' }])], 'inventory.warehouse')} />
                <MenuItem title="Mínimos y máximos" note="Nivel de compra y proveedor preferido" icon="sliders" onClick={() => levelsForm(s, form)} />
                <MenuItem title="Insumo" note="Nombre y unidad base" icon="filter" onClick={() => form('Insumo', [field('name', 'Nombre'), field('unit', 'Unidad base', 'select', 'g', choice(['g', 'ml', 'unit']))], 'inventory.ingredient')} />
                <MenuItem title="Receta o nueva versión" note="Conserva las versiones anteriores" icon="layers" onClick={() => recipe()} />
                <MenuItem title="Vincular receta" note="Aplica a las próximas unidades" icon="swap" onClick={() => form('Próximas unidades usarán esta versión', [select('productId', 'Producto', 'product'), select('recipeId', 'Receta', 'recipe')], 'recipe.bind')} />
                <MenuItem title="Política de inventario" note="Reserva al enviar, consume al liquidar" icon="sliders" onClick={() => form('Reserva al enviar · consume al liquidar', [select('warehouseId', 'Almacén de venta', 'warehouse')], 'inventory.configure', { policy: 'reserve-on-send-consume-on-close' })} />
                <MenuItem title="Semáforos de cocina" note="Amarillo y rojo por estación" icon="clock" onClick={() => form('Tiempos de preparación', [field('name', 'Estación', 'select', '', choice(s.restaurant.settings?.stations || s.restaurant.stations || [])), field('yellowMinutes', 'Amarillo desde minutos', 'number', 7), field('redMinutes', 'Rojo desde minutos', 'number', 15)], 'station.configure')} />
            </ContextMenu>
                <Button className="ghost" icon="refresh" onClick={() => form('Consumo completo comprobado', [field('movementId', 'Consumo', 'select', '', list('stockmovement').filter(x => x.type === 'sale').map(x => ({ value: x.id, label: name('ingredient', x.ingredientId) + ' · ' + (-x.quantity / 1000) + ' · ' + date(x.at) }))), field('reason', 'Motivo y comprobación física')], 'stock.return')}>Devolución</Button>
                <Button className="ghost" icon="swap" onClick={() => form('Entrega de almacén; otra persona debe recibir', [select('fromWarehouseId', 'Origen', 'warehouse'), select('toWarehouseId', 'Destino', 'warehouse'), select('ingredientId', 'Insumo', 'ingredient'), field('quantity', 'Cantidad', 'number', 1), unit, field('reason', 'Motivo')], 'transfer.create')}>Traspasar</Button>
                {dialog && <Button className="ghost" icon="check" onClick={() => dialog(ctx => <CountDialog state={s} ctx={ctx} action={action} />)}>Conteo físico</Button>}
                <Button className="ghost" icon="minus" onClick={() => stockForm('stock.waste')}>Merma</Button>
                <Button className="primary" icon="plus" onClick={() => stockForm('stock.receive')}>Entrada</Button></PageTools>
            <Kpis>
                <MetricCard className="lead" label="Valor del inventario" value={money(stocks.reduce((n, x) => n + (x.value || 0), 0))} note={plural(list('ingredient').length, 'insumo', 'insumos') + ' · ' + plural(list('warehouse').length, 'almacén', 'almacenes')} icon="box" tone="amber" />
                <MetricCard label="Reservado por comandas" value={stocks.filter(x => x.reserved > 0).length} note="insumos con reserva activa" icon="receipt" tone="blue" />
                <MetricCard label="Traspasos por recibir" value={transfers.length} note={transfers[0] ? name('ingredient', transfers[0].ingredientId) + ' · desde ' + name('warehouse', transfers[0].fromWarehouseId) : 'Ninguno pendiente'} icon="swap" tone="purple" />
                <MetricCard label="Bajo mínimo" value={low.length} note={low.length ? low.slice(0, 3).map(i => i.name).join(', ') + ' · ver Compras' : jobs.filter(j => j.status === 'pending').length + ' consumos por liquidar'} icon="alert" tone={low.length ? 'red' : 'green'} />
            </Kpis>
            <div className="g g-side start">
                <section className="card panel"><PanelHeading title="Existencias y reservas" note="Disponible = existencia − reservado" icon="box" action={list('warehouse').length > 1 && <div className="seg sm" role="group" aria-label="Filtrar almacén">{[{ id: 'all', name: 'Todos' }, ...list('warehouse')].map(w => <Button key={w.id} icon={false} className={warehouse === w.id ? 'active' : ''} aria-pressed={warehouse === w.id} onClick={() => setWarehouse(w.id)}>{w.name}</Button>)}</div>} />
                    <DataTable columns={['Insumo', 'Almacén', '>Existencia', '>Reservado', '>Disponible', '>Valor']} rows={shown.map(x => { const u = unitOf(x.ingredientId); return [<span className="w"><b>{name('ingredient', x.ingredientId)}</b>{lowIds.has(x.ingredientId) && <Pill tone="red">Bajo mínimo</Pill>}</span>, name('warehouse', x.warehouseId), qty(x.quantity, u), x.reserved ? <span style={{ color: 'var(--amber)' }}>{qty(x.reserved, u)}</span> : <span className="no">—</span>, <b>{qty(x.quantity - (x.reserved || 0), u)}</b>, money(x.value)]; })} foot={shown.length ? ['Total', '', '', '', '', money(shown.reduce((n, x) => n + (x.value || 0), 0))] : undefined} empty="Registra una entrada para ver existencias." />
                    {moves.length > 0 && <><h4 className="sub-h">Movimientos recientes</h4><div className="rows">{moves.map(m => { const [icon, tone, title] = moveLook[m.type] || ['box', 'neutral', m.type]; return <div className="r" key={m.id}><Sq icon={icon} tone={tone} /><div className="w"><b>{title} · {name('ingredient', m.ingredientId)}</b><span>{(m.quantity > 0 ? '+' : '') + qty(m.quantity, unitOf(m.ingredientId))}{m.reason ? ' · ' + m.reason : ''}{m.reference ? ' · ' + m.reference : ''}</span></div><time>{clock(m.at)}</time></div>; })}</div></>}
                </section>
                <div className="stack">
                    {transfers.map(t => <section className="card tint" key={t.id}><PanelHeading title="Traspaso por recibir" note="Otra persona debe confirmarlo" icon="swap" /><div className="big-num" style={{ fontSize: 30 }}>{qty(t.quantity, unitOf(t.ingredientId))}</div><p style={{ margin: '2px 0 14px', color: 'var(--dock-ink)' }}>{name('ingredient', t.ingredientId)} · {name('warehouse', t.fromWarehouseId)} → {name('warehouse', t.toWarehouseId)}</p><div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}><Button className="primary sm" icon="check" onClick={() => invoke('transfer.receive', { id: t.id })}>Confirmar recepción identificada</Button><Button className="ghost sm" icon="close" onClick={() => form('Cancelar traspaso', [field('reason', 'Motivo')], 'transfer.cancel', { id: t.id })}>Cancelar con motivo</Button></div></section>)}
                    <section className="card panel"><PanelHeading title="Recetas vigentes" note="Cada cambio crea una versión" icon="layers" action={<Button className="ghost sm" icon="plus" onClick={() => recipe()}>Receta</Button>} />
                        {list('recipe').length ? <div className="rows">{list('recipe').map(r => <div className="r" key={r.id}><Sq icon="layers" /><div className="w"><b>{r.name}</b><span>{plural((r.lines || []).length, 'insumo', 'insumos')}</span></div><Pill>Versión {r.version}</Pill><Button className="ghost xs icon-only" icon="plus" aria-label={'Nueva versión de ' + r.name} title="Nueva versión" onClick={() => recipe(r)}>{''}</Button></div>)}</div> : <Empty icon="layers" title="Sin recetas" text="Crea una receta para descontar insumos al vender." />}
                    </section>
                </div>
            </div>
            <VariancePanel state={s} action={action} run={run} /></>;

    }

    if (page === 'blind') {

        const turns = list('cash').filter(c => c.blind).slice().reverse();
        const table = <DataTable columns={['Turno', 'Apertura', 'Estado', '>Contado', '>Diferencia']} rows={turns.map(c => [<code>{c.id.slice(0, 8)}</code>, date(c.openedAt), <StatusBadge value={c.status} label={c.status === 'open' ? 'Abierto' : c.status === 'closed' ? 'Cerrado' : undefined} />, c.counted == null ? '—' : money(c.counted), c.difference == null ? '—' : <span className={c.difference < 0 ? 'neg' : c.difference > 0 ? 'pos' : ''}>{money(c.difference)}</span>])} empty="Aún no hay turnos ciegos." />;
        const openTurn = () => form('Turno de caja', [moneyField('initial', 'Fondo inicial MXN'), ...(manager ? [select('operatorId', 'Cajero responsable', 'user', u => u.role === 'cajero' && u.active)] : [])], 'cash.blind.open', {}, undefined, (p: any) => ({ ...p, initial: cents(p.initial) }));
        if (s.user.role !== 'cajero') return <section className="card panel"><PanelHeading title="Arqueo ciego" note="La cajera cuenta sin ver el esperado" icon="lock" action={<>{!cash && <Button className="ghost sm" icon="plus" onClick={openTurn}>Abrir turno ciego</Button>}{manager && <Button className="ghost sm" icon="edit" onClick={() => form('Conserva el cierre original', [select('id', 'Cierre', 'cash', x => x.status === 'closed'), field('method', 'Medio', 'select', 'cash', choice(['cash', 'card', 'transfer'])), field('direction', 'Ajuste', 'select', 'increase', [{ value: 'increase', label: 'Aumentar' }, { value: 'decrease', label: 'Disminuir' }]), moneyField('amount', 'Importe MXN'), field('reason', 'Motivo')], 'cash.adjust', {}, undefined, (p: any) => ({ ...p, amount: cents(p.amount) }))}>Ajuste autorizado</Button>}</>} />{table}</section>;
        return <BlindCount cash={cash} form={form} openTurn={openTurn} history={table} />;

    }

    if (page === 'delivery') {

        const deliveries = list('delivery').slice().reverse(), proposals = list('cloudproposal').filter(x => x.status === 'pending-review');
        const lane = (st: string) => st === 'accepted-local' ? 'accepted' : st === 'assigned' ? 'assigned' : st === 'out-for-delivery' ? 'out' : ['picked-up', 'reconciled', 'delivered', 'cancelled', 'rejected-local'].includes(st) ? 'closed' : 'pending';
        const by = (key: string) => deliveries.filter(d => lane(d.status) === key);
        const visitTotal = (d: Row) => list('visit').find(v => v.id === d.visitId)?.total;
        // Pickup alert: the scheduled time passed and nobody collected the order.
        const pickupLate = (d: Row) => d.mode === 'pickup' && !!d.pickupAt && lane(d.status) !== 'closed' ? Math.floor((Date.now() - Date.parse(d.pickupAt)) / 60000) : -Infinity;
        const card = (d: Row, actions: React.ReactNode, extra?: React.ReactNode) => { const late = pickupLate(d); return <div className={'kc' + (late > 0 ? ' late' : late > -10 ? ' due' : '')} key={d.id}><b>{d.pickupName || name('customer', d.customerId)} · {d.mode === 'pickup' ? 'Recoger' : 'Entrega'}</b><small>{d.mode === 'pickup' ? (d.pickupAt ? 'Recoge a las ' + clock(d.pickupAt) : 'Recoge en sucursal') : d.addressSnapshot?.text || 'Sin dirección'}{d.courierId ? ' · ' + name('courier', d.courierId) : ''}{d.distanceKm != null ? ' · ' + num(d.distanceKm, 1) + ' km, ≈ ' + d.etaMinutes + ' min' : ''}</small>{late > 0 && <span className="ui-status tone-red"><UiIcon name="alert" />Sin recoger · {late} min</span>}{late <= 0 && late > -10 && <span className="ui-status tone-amber"><UiIcon name="clock" />Recoge en {-late} min</span>}{extra}<div className="row"><span className="num">{visitTotal(d) != null ? money(visitTotal(d)) : money(d.fee)}</span><span className="actions"><Button className="ghost xs" icon="receipt" onClick={() => openVisit(d.visitId)}>Cuenta</Button>{actions}</span></div></div>; };
        const pendingCash = by('out').reduce((n, d) => n + ((d.responsibility || 0) - (d.reconciled || 0)), 0);
        const platforms = platformCards(s, { action, run, form, openVisit, manager });
        const lanes: [string, string, string, React.ReactNode[]][] = [
            ['pending', 'Por aceptar', 'var(--amber-bar)', [...platforms.pending, ...proposals.map(p => <div className="kc" key={p.id}><b>Pedido web · {p.command?.payload?.name || 'Cliente'}</b><small>Revisión local antes de aceptar</small><StatusBadge value="pending-review" label="Revisión local" /><div className="row"><span className="num">{money(p.command?.payload?.quotedTotal)}</span><Button className="primary xs" icon="check" onClick={() => form('Decisión local autorizada', [flag('accept', 'Aceptar después de revisar disponibilidad'), field('reason', 'Motivo')], 'commerce.decide', { id: p.id })}>Aceptar o rechazar</Button></div></div>), ...by('pending').map(d => card(d, null, <StatusBadge value={d.status} />))]],
            ['accepted', 'Aceptados', 'var(--blue)', [...platforms.accepted, ...by('accepted').map(d => card(d, <>{d.mode === 'pickup' && <Button className="ghost xs" icon="check" onClick={() => invoke('delivery.pickup', { id: d.id })}>Confirmar recogida</Button>}{manager && d.mode === 'delivery' && <Button className="ghost xs" icon="users" onClick={() => form('Responsabilidad pendiente', [select('courierId', 'Repartidor', 'courier', x => x.active)], 'delivery.assign', { id: d.id })}>Asignar repartidor</Button>}</>))]],
            ['assigned', 'Asignados', 'var(--purple)', by('assigned').map(d => card(d, <Button className="ghost xs" icon="truck" onClick={() => invoke('delivery.dispatch', { id: d.id })}>Confirmar salida</Button>))],
            ['out', 'En reparto', 'var(--amber)', by('out').map(d => card(d, manager && <Button className="primary xs" icon="wallet" onClick={() => form('Efectivo o comprobante revisado', [moneyField('amount', 'Importe MXN', ((d.responsibility || 0) - (d.reconciled || 0)) / 100), field('method', 'Medio', 'select', 'cash', choice(['cash', 'card', 'transfer'])), field('reference', 'Referencia y comprobación')], 'delivery.reconcile', { id: d.id }, undefined, (p: any) => ({ ...p, amount: cents(p.amount) }))}>Conciliar</Button>, <Pill tone="purple" icon="wallet">Pendiente {money((d.responsibility || 0) - (d.reconciled || 0))}</Pill>))],
            ['closed', 'Cerrados', 'var(--green)', [...platforms.closed, ...by('closed').map(d => card(d, null, <StatusBadge value={d.status} />))]],
        ];
        return <>
            <PageTools><Button className="ghost" icon="user" onClick={() => form('Cliente', [field('name', 'Nombre'), field('phone', 'Teléfono'), field('notes', 'Notas', 'textarea')], 'customer.save')}>Cliente</Button>
                {simOn(s, 'callerid') && <Button className="ghost" icon="phone" onClick={() => simulateCall(form)}>Simular llamada</Button>}
                {manager && simOn(s, 'aggregators') && <Button className="ghost" icon="truck" onClick={() => simulatePlatformOrder(s, form)}>Pedido de plataforma</Button>}
                <Button className="ghost" icon="pin" onClick={() => activeOn(s, 'maps') ? form('Dirección de entrega', [select('customerId', 'Cliente', 'customer'), field('label', 'Etiqueta'), field('text', 'Dirección completa', 'textarea'), { ...flag('geocode', liveOn(s, 'maps') ? 'Ubicar con Google Maps' : 'Ubicar con el mapa simulado', true), hint: liveOn(s, 'maps') ? 'Google calcula las coordenadas, la distancia y el tiempo en unos segundos. Desmárcalo para capturarlas a mano.' : 'Calcula las coordenadas a partir de la dirección. Desmárcalo para capturarlas a mano.' }, { ...field('lat', 'Latitud', 'number', 0), required: false, showIf: (x: any) => !x.geocode }, { ...field('lon', 'Longitud', 'number', 0), required: false, showIf: (x: any) => !x.geocode }], 'address.save', {}, undefined, (p: any) => p.geocode ? { customerId: p.customerId, label: p.label, text: p.text, geocode: true } : { customerId: p.customerId, label: p.label, text: p.text, lat: p.lat, lon: p.lon }) : form('Dirección y coordenadas manuales', [select('customerId', 'Cliente', 'customer'), field('label', 'Etiqueta'), field('text', 'Dirección completa', 'textarea'), field('lat', 'Latitud', 'number', 0), field('lon', 'Longitud', 'number', 0)], 'address.save')}>Dirección</Button>
                {manager && <ContextMenu label="Zonas y repartidores" text="Zonas y repartidores" icon="settings">
                    <MenuItem title="Repartidor" note="Alta de repartidor" icon="users" onClick={() => form('Repartidor', [field('name', 'Nombre')], 'courier.save')} />
                    <MenuItem title="Zona y tarifa" note="Polígono local con tarifa" icon="pin" onClick={() => form('Polígono local', [field('name', 'Nombre'), moneyField('fee', 'Tarifa MXN'), field('priority', 'Prioridad (menor primero)', 'number', 0), { key: 'vertices', label: 'Vértices de la zona', type: 'rows', value: '', hint: 'Al menos tres puntos, en orden.', rows: { columns: [{ key: 'lat', label: 'Latitud', type: 'number' as const, placeholder: '19.4326' }, { key: 'lon', label: 'Longitud', type: 'number' as const, placeholder: '-99.1332' }], split: (l: string) => l.split(',').map(x => x.trim()), join: (c: string[]) => c.join(','), add: 'Agregar vértice' } }], 'zone.save', {}, undefined, (p: any) => ({ name: p.name, fee: cents(p.fee), priority: p.priority, polygon: String(p.vertices).split('\n').filter(Boolean).map(line => { const c = line.split(',').map(x => x.trim()); if (c.length !== 2) throw new Error('Vértice: latitud,longitud'); return { lat: c[0], lon: c[1] }; }) }))} />
                    <MenuItem title="Recepción de pedidos web" note="Identidad central de la sucursal" icon="cloud" onClick={() => form('Identidad central de sucursal', [field('tenantId', 'Empresa', 'text', s.restaurant.tenantId || ''), field('branchId', 'Sucursal central', 'text', s.restaurant.branchId || ''), select('waiterId', 'Responsable local', 'user', x => x.role === 'mesero' && x.active), flag('enabled', 'Habilitar propuestas firmadas', true)], 'commerce.configure')} />
                </ContextMenu>}
                <Button className="primary" icon="plus" onClick={() => form('Pedido local', [select('customerId', 'Cliente', 'customer'), field('mode', 'Servicio', 'select', 'pickup', [{ value: 'pickup', label: 'Recoger en sucursal' }, { value: 'delivery', label: 'Entrega a domicilio' }]), { key: 'pickupAt', label: 'Hora de recogida', type: 'datetime-local', required: false, value: new Date(Date.now() + 1800000 - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16), showIf: (x: any) => x.mode === 'pickup', hint: 'Avisa en rojo si llega la hora y no lo han recogido.' }, { key: 'pickupName', label: 'Nombre para entregar', type: 'text', required: false, placeholder: 'Por defecto, el del cliente', showIf: (x: any) => x.mode === 'pickup' }, { ...field('addressId', 'Dirección de entrega', 'select', '', options('address')), showIf: (x: any) => x.mode === 'delivery' }], 'delivery.create', {}, undefined, (p: any) => ({ customerId: p.customerId, mode: p.mode, ...(p.mode === 'delivery' ? { addressId: p.addressId } : { pickupAt: p.pickupAt ? new Date(p.pickupAt).toISOString() : '', pickupName: p.pickupName || '' }) }))}>Nuevo pedido</Button></PageTools>
            <CallBanner state={s} action={action} run={run} form={form} />
            {deliveries.filter(d => pickupLate(d) > 0).length > 0 && <Notice tone="warn" icon="alert"><b>{plural(deliveries.filter(d => pickupLate(d) > 0).length, 'pedido para llevar pasó', 'pedidos para llevar pasaron')} su hora de recogida.</b> {deliveries.filter(d => pickupLate(d) > 0).map(d => (d.pickupName || name('customer', d.customerId)) + ' (' + clock(d.pickupAt) + ')').join(', ')}</Notice>}
            <Kpis>
                <MetricCard label="Pedidos activos" value={proposals.length + platforms.pending.length + platforms.accepted.length + deliveries.filter(d => lane(d.status) !== 'closed').length} note={deliveries.filter(d => lane(d.status) !== 'closed' && d.mode === 'delivery').length + ' entregas · ' + deliveries.filter(d => lane(d.status) !== 'closed' && d.mode === 'pickup').length + ' para recoger' + (platforms.accepted.length ? ' · ' + platforms.accepted.length + ' de plataformas' : '')} icon="truck" tone="blue" />
                <MetricCard label="Por aceptar" value={proposals.length + platforms.pending.length} note={platforms.pending.length ? plural(platforms.pending.length, 'de plataformas', 'de plataformas') + ' · ' + proposals.length + ' web' : 'Pedidos web firmados'} icon="cloud" tone="amber" />
                <MetricCard label="Pendiente de conciliar" value={money(pendingCash)} note={plural(by('out').length, 'pedido en reparto', 'pedidos en reparto')} icon="wallet" tone="purple" />
                <MetricCard label="Cerrados" value={by('closed').length} note={by('closed').filter(d => isToday(d.at || d.updatedAt)).length + ' hoy'} icon="check" tone="green" />
            </Kpis>
            <div className="kanban stagger">{lanes.map(([key, title, color, cards]) => <div className="lane" key={key}><h4><span><span className="dot" style={{ background: color }} />{title}</span><span className="c">{cards.length}</span></h4>{cards.length ? (key === 'closed' ? cards.slice(0, 3) : cards) : <p className="lane-empty">Sin pedidos</p>}{key === 'closed' && cards.length > 3 && <p className="lane-more">y {cards.length - 3} más</p>}</div>)}</div>
            <section className="card panel"><PanelHeading title="Clientes y direcciones" note={plural(list('customer').length, 'cliente registrado', 'clientes registrados')} icon="users" /><DataTable columns={['Cliente', 'Teléfono', 'Direcciones', '>Pedidos']} rows={list('customer').map(c => [<b>{c.name}</b>, c.phone, list('address').filter(a => a.customerId === c.id).map(a => a.label + ': ' + a.text + (['queued', 'sending'].includes(a.status) ? ' (ubicando…)' : ['failed', 'uncertain'].includes(a.status) ? ' (sin ubicar)' : '')).join(' · ') || '—', list('visit').filter(v => v.customerId === c.id).length])} empty="Registra un cliente para tomar pedidos." /></section></>;

    }

    if (page === 'printing') {

        const jobs = list('printjob').slice().reverse(), today = jobs.filter(j => isToday(j.at));
        return <>
            <PageTools><Button className="ghost" icon="cash" onClick={() => form('Solicitud de cajonera', [field('reason', 'Motivo')], 'drawer.request')}>Solicitar apertura de cajonera</Button></PageTools>
            {simOn(s, 'printer') ? <Notice tone="info" icon="spark"><b>Impresora y cajón simulados.</b> Cada trabajo se resuelve como «Simulado»: no sale papel ni se abre el cajón físico.</Notice>
                : <Notice tone="info">Los adaptadores físicos permanecen aislados. <b>Conciliar no vuelve a cobrar</b> ni duplica la cuenta.</Notice>}
            <Kpis>
                <MetricCard label="Trabajos de hoy" value={today.length} note={today.filter(j => j.type !== 'drawer').length + ' cuentas · ' + today.filter(j => j.type === 'drawer').length + ' cajonera'} icon="print" tone="blue" />
                <MetricCard label="Comprobados" value={jobs.filter(j => ['printed', 'confirmed'].includes(j.status)).length} note={jobs.some(j => j.status === 'simulated') ? plural(jobs.filter(j => j.status === 'simulated').length, 'simulado', 'simulados') + ' aparte' : 'Impresión confirmada'} icon="check" tone="green" />
                <MetricCard label="Por conciliar" value={jobs.filter(j => ['uncertain', 'submitted'].includes(j.status)).length} note="Resultado incierto o enviado" icon="clock" tone="amber" />
                <MetricCard className={jobs.some(j => j.status === 'failed') ? 'danger' : ''} label="Fallidos" value={jobs.filter(j => j.status === 'failed').length} note="Requieren reimpresión" icon="alert" tone="red" />
            </Kpis>
            <div className="g g-side">
                <section className="card panel"><PanelHeading title="Trabajos de impresión" note="Más recientes primero" icon="print" /><DataTable columns={['Trabajo', 'Hora', 'Estado', 'Evidencia', '']} rows={jobs.map(j => [<><b>{j.type === 'drawer' ? 'Cajonera' : j.type === 'zreport' ? 'Corte Z' : 'Cuenta'}</b><small><code>{j.id.slice(0, 8)}</code></small></>, clock(j.at), <StatusBadge value={j.status} />, j.evidence || '—', <span style={{ display: 'flex', gap: 6, justifyContent: 'flex-end', flexWrap: 'wrap' }}>{['uncertain', 'submitted'].includes(j.status) && <Button className="primary xs" icon="check" onClick={() => form('Revisión del dispositivo', [field('status', 'Resultado', 'select', 'uncertain', [{ value: 'uncertain', label: 'No comprobado' }, { value: 'confirmed', label: 'Comprobado' }, { value: 'failed', label: 'Fallo comprobado' }]), field('evidence', 'Evidencia física o del driver')], 'print.resolve', { id: j.id, attemptId: j.attemptId })}>Conciliar resultado físico</Button>}{['failed', 'uncertain'].includes(j.status) && <Button className="ghost xs" icon="refresh" onClick={() => form('Puede producir otra copia física', [field('reason', 'Motivo de reimpresión')], 'print.retry', { id: j.id })}>Crear reimpresión autorizada</Button>}</span>])} empty="Los trabajos de impresión aparecerán aquí." /></section>
                <section className="card panel"><PanelHeading title="Qué significa cada estado" note="Antes de conciliar, revisa el papel o la cajonera" icon="info" /><div className="rows">{[['submitted', 'El trabajo salió; falta confirmar que se imprimió.'], ['uncertain', 'No hubo respuesta. Revisa físicamente antes de decidir.'], ['failed', 'Comprobado que no salió. Crea una reimpresión autorizada.'], ['confirmed', 'Comprobado en caja: el papel salió o el cajón abrió.']].map(([st, text]) => <div className="r" key={st} style={{ alignItems: 'flex-start' }}><StatusBadge value={st} /><span className="w"><span style={{ whiteSpace: 'normal' }}>{text}</span></span></div>)}</div></section>
            </div></>;

    }

    if (page === 'fiscal') {

        // A submission the PAC never answered waits for a manager, who first checks in Facturama that the folio does not exist.
        const unanswered = (f: Row) => f.status === 'pending-reconciliation' && !f.providerId;
        const rows = list('fiscal').slice().reverse(), fix = rows.filter(f => ['validation-blocked', 'failed', 'rejected', 'simulated-rejected'].includes(f.status) || unanswered(f)), pac = simOn(s, 'pac'), real = liveOn(s, 'pac'), production = real && s.connection?.fiscal === 'production';
        const closed = (v: Row) => v.status === 'closed', uuid = (f: Row) => f.fiscalUuid || f.sandboxUuid;
        const cancel = (f: Row) => form(f.status === 'simulated-stamped' ? 'Cancelar CFDI simulado' : 'Cancelar CFDI ' + uuid(f), [field('motive', 'Motivo SAT', 'select', '02', [{ value: '01', label: '01 · Con errores, con relación' }, { value: '02', label: '02 · Con errores, sin relación' }, { value: '03', label: '03 · No se llevó a cabo la operación' }, { value: '04', label: '04 · Operación nominativa en factura global' }]), { ...field('replacementUuid', 'UUID que la sustituye'), required: false, showIf: (x: any) => x.motive === '01' }, field('reason', 'Motivo interno')], 'fiscal.cancel.request', { id: f.id });
        return <>
            <PageTools><Button className="ghost" icon="settings" onClick={() => form('Portal público separado', [field('url', 'URL HTTPS', 'url')], 'fiscal.portal.configure')}>Configurar URL del portal</Button>
                <Button className="ghost" icon="key" onClick={() => form('Token con vigencia de 24 horas', [select('visitId', 'Ticket cerrado', 'visit', closed)], 'fiscal.token', {}, undefined, (p: any) => p)}>Enlace de autofacturación</Button>
                <Button className="primary" icon="plus" onClick={() => form('Datos de receptor', [select('visitId', 'Ticket cerrado', 'visit', closed), field('rfc', 'RFC'), field('name', 'Razón social'), field('postalCode', 'Código postal fiscal'), field('regime', 'Régimen fiscal'), field('use', 'Uso CFDI'), { ...field('email', 'Correo para enviar la factura', 'email'), required: false }], 'fiscal.request')}>Solicitud fiscal</Button></PageTools>
            {production ? <Notice tone="ok" icon="file"><b>Facturama en producción.</b> Cada solicitud se timbra con validez fiscal ante el SAT con el CSD del emisor; cancelar también es definitivo.</Notice>
                : real ? <Notice tone="info" icon="file"><b>Facturama sandbox.</b> Las solicitudes se timbran en el ambiente de pruebas de Facturama: <b>sin validez fiscal</b>.</Notice>
                    : pac ? <Notice tone="info" icon="spark"><b>PAC simulado activo.</b> Timbra con un UUID de prueba y aplica las reglas del SAT al receptor, pero <b>las facturas no tienen validez fiscal</b>.</Notice>
                        : <Notice tone="warn"><b>CFDI 4.0 sin PAC.</b> Una solicitud pendiente no es una factura timbrada. Activa Facturama (real o simulado) en Integraciones para timbrar.</Notice>}
            <Kpis>
                <MetricCard label="Solicitudes" value={rows.length} note="Registradas en la sucursal" icon="file" tone="blue" />
                <MetricCard className={fix.length ? 'danger' : ''} label="Requieren corrección" value={fix.length} note="Validación, envío o rechazo del PAC" icon="alert" tone="red" />
                <MetricCard label="En proceso" value={rows.filter(f => ['pending', 'validating', 'validated', 'submitting', 'pending-review', 'submitted'].includes(f.status)).length} note={pac ? 'Pendientes de timbrar' : 'Enviadas al PAC'} icon="clock" tone="amber" />
                {production ? <MetricCard label="Timbradas" value={rows.filter(f => f.status === 'stamped').length} note={rows.filter(f => f.status === 'cancelled').length + ' canceladas · con validez fiscal'} icon="check" tone="green" />
                    : <MetricCard label="Timbradas de prueba" value={rows.filter(f => ['sandbox-stamped', 'simulated-stamped'].includes(f.status)).length} note={rows.filter(f => ['sandbox-cancelled', 'simulated-cancelled'].includes(f.status)).length + ' canceladas · sin validez fiscal'} icon="check" tone="green" />}
            </Kpis>
            <section className="card panel"><PanelHeading title="Solicitudes fiscales" note="Más recientes primero" icon="file" /><DataTable columns={['Ticket', 'Receptor', 'Estado', 'Mensaje', 'UUID fiscal', '']} rows={rows.map(f => [<code>{f.visitId?.slice(0, 8) || '—'}</code>, <span className="w"><b>{f.receiver?.rfc}</b><small>{f.receiver?.name}</small></span>, <StatusBadge value={f.status} />, <span className="w"><span style={{ whiteSpace: 'normal' }}>{f.message || '—'}</span></span>, uuid(f) ? <span className="w"><code>{uuid(f)}</code>{f.emailStatus && <small>{f.emailStatus === 'sent' ? 'Enviada por correo a ' + f.receiver?.email : 'No se pudo enviar por correo'}</small>}</span> : '—', <span className="row-actions">{manager && unanswered(f) && <Button className="primary xs" icon="refresh" onClick={() => form('Reintentar con el folio ' + f.folio, [field('reason', 'Revisé Facturama y el folio no existe')], 'fiscal.retry', { id: f.id })}>Reintentar</Button>}{pac && f.status === 'pending' && <Button className="primary xs" icon="check" onClick={() => invoke('pac.stamp', { id: f.id })}>Timbrar (simulado)</Button>}{manager && ['stamped', 'sandbox-stamped', 'simulated-stamped'].includes(f.status) && <Button className="ghost xs" icon="close" onClick={() => cancel(f)}>Cancelar</Button>}</span>])} empty="Las solicitudes fiscales aparecerán aquí." />{result && !result.fiscalUuid && <pre className="audit-json">{JSON.stringify(result, null, 2)}</pre>}</section></>;

    }

    if (page === 'analytics') {

        const a = s.analytics || {};
        const closes: any[] = (a.cashCloses || []).slice(-7);
        return <>
            <Kpis>
                <MetricCard className="lead" label="Venta liquidada" value={money(a.sales)} note="Espejo de eventos de la sucursal" icon="wallet" tone="amber" />
                <MetricCard label="Mesas en servicio" value={a.openTables || 0} note={'Cuentas abiertas: ' + (a.openAccounts || 0)} icon="table" tone="blue" />
                <MetricCard label="Actualidad de los datos" value={a.lagSeconds == null ? '—' : <>{a.lagSeconds} <small>s</small></>} note={a.receivedAt ? 'Recibido ' + clock(a.receivedAt) : 'Sin sincronización inicial'} icon="refresh" tone="green" />
            </Kpis>
            <div className="g g-side">
                <section className="card panel"><PanelHeading title="Efectivo contado por cierre" note="Últimos cierres de caja" icon="chart" />{closes.length ? <BarChart labels={closes.map(c => new Date(c.closedAt).toLocaleDateString('es-MX', { weekday: 'short', day: 'numeric' }))} values={closes.map(c => (c.counted || 0) / 100)} highlight={closes.length - 1} format={v => '$' + v.toLocaleString('es-MX', { maximumFractionDigits: 0 })} tick={v => '$' + (v >= 1000 ? (v / 1000) + ' k' : v)} /> : <Empty icon="chart" title="Sin cierres sincronizados" text="Los cierres de caja aparecerán al sincronizar." />}</section>
                <section className="card panel"><PanelHeading title="Origen de la información" icon="info" /><div className="rows"><div className="r"><div className="w"><b>Fuente</b><span>{a.source || 'Sin sincronizar'}</span></div></div><div className="r"><div className="w"><b>Origen</b><span>{date(a.sourceAt)}</span></div></div><div className="r"><div className="w"><b>Recibido</b><span>{date(a.receivedAt)}</span></div></div><div className="r"><div className="w"><b>Incidencias</b><span>{(a.incidents || []).length ? (a.incidents || []).map((i: any) => i.reason).join(' · ') : 'Sin incidencias registradas'}</span></div>{!(a.incidents || []).length && <Pill tone="green" icon="check">Al día</Pill>}</div></div></section>
            </div>
            <section className="card panel"><PanelHeading title="Cierres de caja" note="Contado contra esperado" icon="history" /><DataTable columns={['Cierre', '>Contado', '>Esperado', '>Diferencia']} rows={(a.cashCloses || []).slice().reverse().map((c: any) => [date(c.closedAt), money(c.counted), money(c.expected), <span className={c.difference < 0 ? 'neg' : c.difference > 0 ? 'pos' : ''}>{money(c.difference)}</span>])} empty="Sin cierres sincronizados." /></section></>;

    }

    if (page === 'reports') return <Reports state={s} manager={manager} run={run} extra={manager && dialog && confirm ? <><ClosingsPanel state={s} action={action} run={run} dialog={dialog} confirm={confirm} /><AbcPanel action={action} run={run} /></> : null} />;
    return null;

}

function BlindCount({ cash, form, openTurn, history }: { cash?: Row; form: any; openTurn: () => void; history: React.ReactNode }) {

    const denominations = [100000, 50000, 20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50, 20, 10];
    const [counts, setCounts] = useState<Record<number, any>>({}), [card, setCard] = useState(''), [transfer, setTransfer] = useState('');
    const set = (d: number, n: number) => setCounts(c => ({ ...c, [d]: Math.max(0, Math.floor(n || 0)) }));
    const num = (d: number) => Number(counts[d]) || 0;
    const cashTotal = denominations.reduce((t, d) => t + d * (Number(counts[d]) || 0), 0);
    const safe = (v: string) => { try { return v ? cents(v) : 0; } catch { return 0; } };
    const total = cashTotal + safe(card) + safe(transfer);
    if (!cash) return <div className="g g-side start"><section className="card panel"><PanelHeading title="Turno de caja" note="Abre tu turno antes de contar" icon="cash" /><Empty icon="lock" title="No tienes un turno abierto" text="Captura el fondo inicial para comenzar." action={<Button className="primary sm" icon="plus" onClick={openTurn}>Abrir turno ciego</Button>} /></section><section className="card panel"><PanelHeading title="Turnos anteriores" icon="history" />{history}</section></div>;
    return <div className="g g-side start">
        <div className="stack"><section className="card panel"><PanelHeading title="Efectivo en caja" note={'Turno abierto ' + clock(cash.openedAt) + ' · fondo inicial ' + money(cash.initial)} icon="cash" action={<Pill>{denominations.filter(d => Number(counts[d]) > 0).length} denominaciones capturadas</Pill>} />
            <div className="denoms stagger">{denominations.map(d => <div className={'denom' + (Number(counts[d]) > 0 ? '' : ' zero')} key={d}><b className="num">{money(d).replace('.00', '')}</b><div className="stepper"><Button type="button" icon={false} aria-label={'Quitar una de ' + money(d)} onClick={() => set(d, num(d) - 1)}>−</Button><input type="number" min={0} inputMode="numeric" aria-label={'Cantidad de ' + money(d)} placeholder="0" value={counts[d] ?? ''} onFocus={e => e.target.select()} onChange={e => setCounts(c => ({ ...c, [d]: e.target.value === '' ? '' : Math.max(0, Math.floor(Number(e.target.value))) }))} /><Button type="button" icon={false} aria-label={'Agregar una de ' + money(d)} onClick={() => set(d, num(d) + 1)}>+</Button></div><span>{money(d * (Number(counts[d]) || 0))}</span></div>)}</div></section>
            <section className="card panel"><PanelHeading title="Turnos anteriores" note="Tus cierres confirmados" icon="history" />{history}</section></div>
        <section className="card tint"><small style={{ color: 'var(--dock-ink)' }}>Total contado</small><div className="big-num">{money(total)}</div>
            <div className="rows" style={{ marginTop: 12 }}>{[['Efectivo', cashTotal], ['Tarjeta', safe(card)], ['Transferencias', safe(transfer)]].map(([a, v]) => <div className="r" key={a as string} style={{ padding: '8px 0', borderColor: 'var(--dock-edge)' }}><span className="w" style={{ color: 'var(--dock-ink)' }}>{a}</span><span className="amt num">{money(v as number)}</span></div>)}</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 14, marginTop: 14 }}><label>Tarjeta contada MXN<input type="number" min={0} step="0.01" value={card} onChange={e => setCard(e.target.value)} placeholder="0.00" /></label><label>Transferencias contadas MXN<input type="number" min={0} step="0.01" value={transfer} onChange={e => setTransfer(e.target.value)} placeholder="0.00" /></label></div>
            <div className="notice warn" style={{ marginTop: 16, padding: '12px 14px' }}><UiIcon name="alert" /><span>El cierre es definitivo. No podrás modificar el conteo.</span></div>
            <div style={{ marginTop: 16 }}><Button className="primary lg wide" icon="lock" onClick={() => form('Arqueo ciego · cierre definitivo', [], 'cash.blind.close', { id: cash.id, denominations: denominations.map(value => ({ value, count: Number(counts[value]) || 0 })), card: safe(card), transfer: safe(transfer) }, 'Confirmas ' + money(total) + ' contados: efectivo ' + money(cashTotal) + ', tarjeta ' + money(safe(card)) + ' y transferencias ' + money(safe(transfer)) + '. El cierre no se puede modificar.')}>Contar y confirmar cierre</Button></div>
        </section>
    </div>;

}

function Reports({ state: s, manager, run, extra }: { state: any; manager: boolean; run: any; extra?: React.ReactNode }) {

    const iso = (d: Date) => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
    const days = (n: number) => { const d = new Date(); d.setDate(d.getDate() - n); return iso(d); };
    const [from, setFrom] = useState(days(6)), [until, setUntil] = useState(iso(new Date())), [result, setResult] = useState<any>(null);
    const query = (f = from, u = until, after = '') => run(async () => { const r = await native('report', { from: f ? new Date(f + 'T00:00:00').toISOString() : '', until: u ? new Date(u + 'T23:59:59.999').toISOString() : '', after }); setResult((old: any) => ({ ...r, verification: old?.verification })); }, 'Reporte consultado');
    useEffect(() => { native('report', { from: new Date(from + 'T00:00:00').toISOString(), until: new Date(until + 'T23:59:59.999').toISOString(), after: '' }).then(setResult).catch(() => {}); }, []);
    const preset = (f: string, u: string) => { setFrom(f); setUntil(u); void query(f, u); };
    const start = new Date(from + 'T00:00:00'), end = new Date(until + 'T23:59:59');
    const span = Math.min(31, Math.max(1, Math.round((end.getTime() - start.getTime()) / 86400000)));
    const buckets = Array.from({ length: span }, (_, i) => { const d = new Date(end); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - (span - 1 - i)); return d; });
    const totals = buckets.map(d => (s.visits || []).filter((v: Row) => v.openedAt && new Date(v.openedAt).toDateString() === d.toDateString()).reduce((n: number, v: Row) => n + (v.total || 0), 0) / 100);
    const labels = buckets.map(d => d.toLocaleDateString('es-MX', span > 10 ? { day: 'numeric' } : { weekday: 'short', day: 'numeric' }));
    const best = totals.indexOf(Math.max(...totals));
    const ranked = buckets.map((d, i) => ({ d, v: totals[i] })).filter(x => x.v > 0).sort((a, b) => b.v - a.v).slice(0, 5);
    return <>
        <PageTools>{manager && <Button className="ghost" icon="shield" onClick={() => run(async () => { const verified = await native('audit.verify'); setResult((r: any) => ({ ...r, verification: verified })); }, 'Auditoría verificada')}>Verificar auditoría</Button>}</PageTools>
        <div className="filterbar"><div className="input-row" style={{ paddingLeft: 6 }}><div className="chips">{[['Hoy', iso(new Date()), iso(new Date())], ['Últimos 7 días', days(6), iso(new Date())], ['Este mes', iso(new Date(new Date().getFullYear(), new Date().getMonth(), 1)), iso(new Date())]].map(([t, f, u]) => <button type="button" key={t} className="chip" aria-pressed={from === f && until === u} onClick={() => preset(f, u)}>{t}</button>)}</div><label className="sr-only" htmlFor="report-from">Desde</label><input id="report-from" type="date" aria-label="Desde" value={from} onChange={e => setFrom(e.target.value)} style={{ width: 160 }} /><span style={{ color: 'var(--faint)', alignSelf: 'center' }}>a</span><input type="date" aria-label="Hasta" value={until} onChange={e => setUntil(e.target.value)} style={{ width: 160 }} /></div><Button className="primary sm" icon="search" onClick={() => query()}>Consultar</Button></div>
        {result && <Kpis>
            <MetricCard className="lead" label="Venta total" value={money(result.total)} note={plural(result.count ?? 0, 'cuenta', 'cuentas') + (result.count ? ' · ticket ' + money(Math.round(result.total / result.count)) : '')} icon="chart" tone="amber" />
            <MetricCard label="Pagado" value={money(result.paid)} note={result.total ? (result.paid / result.total * 100).toFixed(1) + ' % de la venta' : 'Sin ventas'} icon="wallet" tone="green" />
            <MetricCard label="Propinas" value={money(result.tips)} note={result.paid ? (result.tips / result.paid * 100).toFixed(1) + ' % sobre lo pagado' : 'Sin pagos'} icon="star" tone="purple" />
            <MetricCard label="Saldo pendiente" value={money(result.balance)} note="Cuentas sin liquidar" icon="receipt" tone="blue" />
        </Kpis>}
        <div className="g g-side">
            <section className="card panel"><PanelHeading title="Venta por día" note="Según la fecha de apertura de la cuenta" icon="chart" /><BarChart labels={labels} values={totals} highlight={totals.some(v => v > 0) ? best : undefined} format={v => '$' + v.toLocaleString('es-MX', { maximumFractionDigits: 0 })} tick={v => '$' + (v >= 1000 ? (v / 1000) + ' k' : v)} /></section>
            <section className="card panel"><PanelHeading title="Mejores días" icon="table" />{ranked.length ? <div className="rows">{ranked.map((x, i) => <div className="r" key={i}><span className="num" style={{ width: 18, color: 'var(--faint)', fontWeight: 600 }}>{i + 1}</span><div className="w"><b>{x.d.toLocaleDateString('es-MX', { weekday: 'short', day: 'numeric', month: 'short' })}</b><div style={{ marginTop: 6 }}><Bar value={x.v} max={ranked[0].v} tone={i ? 'm' : ''} /></div></div><span className="amt num">{money(Math.round(x.v * 100))}</span></div>)}</div> : <Empty icon="chart" title="Sin ventas en el periodo" text="Elige otro rango de fechas." />}</section>
        </div>
        {extra}
        {result && <section className="card panel"><PanelHeading title="Cuentas del periodo" note={plural(result.count ?? 0, 'cuenta', 'cuentas') + ' · periodo según fecha de apertura'} icon="receipt" action={<Button className="ghost sm" icon="right" disabled={!result.after} onClick={() => query(from, until, result.after)}>Siguiente página</Button>} /><DataTable columns={['Cuenta', 'Apertura', 'Estado', '>Total', '>Pagado', '>Saldo']} rows={(result.visits || []).map((v: Row) => [<code>{v.id.slice(0, 8)}</code>, date(v.openedAt), <StatusBadge value={v.status} />, money(v.total), money(v.paid), money(v.balance)])} empty="No hay cuentas en el periodo." />
            {result.verification && <div style={{ marginTop: 16 }}><Notice tone={result.verification.valid === false ? 'warn' : 'ok'} icon="shield"><b>{result.verification.valid === false ? 'Se detectó una inconsistencia.' : result.verification.valid === true ? 'Auditoría verificada.' : 'Consulta completada.'}</b> {result.verification.count ?? result.verification.checked ?? 0} registros revisados.</Notice></div>}</section>}
    </>;

}

const MODULES: Record<string, string> = { reservations: 'Reservaciones', reviews: 'Evaluaciones', customerRequests: 'Solicitudes de clientes', printing: 'Impresión', courses: 'Tiempos de servicio', promotions: 'Promociones', multiBranch: 'Multisucursal' };
const SERVICES: [string, string][] = [['usageUntil', 'Derecho de uso'], ['supportUntil', 'Soporte'], ['hostingUntil', 'Alojamiento'], ['updatesUntil', 'Actualizaciones']];
export function ProviderPages({ page, state: s, form, action, run }: Omit<Props, 'openVisit'>) {

    const [result, setResult] = useState<any>(null);
    const rows = (key: string): Row[] => s[key] || [];
    const opts = (key: string) => rows(key).map(r => ({ value: r.id, label: r.name || r.manifest?.version || r.id }));
    const invoke = (type: string, p: any) => run(async () => setResult(await action(type, p)));
    const edit = (r?: Row) => form('Registro comercial de sucursal', [field('name', 'Nombre', 'text', r?.name || ''), field('siteId', 'Identidad real de sucursal', 'text', r?.siteId || ''), field('status', 'Estado', 'select', r?.status || 'active', choice(['active', 'suspended'])), field('planId', 'Plan', 'select', r?.planId || '', opts('plans')), field('mode', 'Modalidad', 'select', r?.commercial?.mode || 'licencia', choice(['renta', 'licencia', 'codigo'])), field('deployment', 'Despliegue', 'select', r?.deployment || 'central', choice(['central', 'dedicated', 'distributor'])), field('distributor', 'Distribuidor', 'text', r?.distributor || ''), field('dedicatedUrl', 'Destino dedicado', 'text', r?.dedicatedUrl || ''), field('clientCertificateSha256', 'Huella del certificado mTLS', 'text', r?.clientCertificateSha256 || '')], 'owner.restaurant', r ? { id: r.id } : {});
    const json = result && <pre className="audit-json">{JSON.stringify(result, null, 2)}</pre>;
    const plan = (id: string) => rows('plans').find(p => p.id === id)?.name || '—';
    if (page === 'overview') {

        const restaurants = rows('restaurants');
        return <>
            <PageTools><Button className="ghost" icon="lock" onClick={() => form('Cambiar contraseña del proveedor', [field('currentPassword', 'Contraseña actual', 'password'), field('newPassword', 'Nueva contraseña', 'password')], 'owner.password')}>Seguridad de mi cuenta</Button><Button className="primary" icon="plus" onClick={() => edit()}>Registrar restaurante</Button></PageTools>
            <Kpis>
                <MetricCard label="Restaurantes" value={restaurants.length} note={plural(restaurants.filter(r => r.status === 'active').length, 'activo', 'activos') + ' · ' + plural(restaurants.filter(r => r.status !== 'active').length, 'suspendido', 'suspendidos')} icon="store" tone="blue" />
                <MetricCard label="Instalaciones" value={rows('installations').length} note="Credenciales separadas" icon="monitor" tone="purple" />
                <MetricCard label="Publicaciones activas" value={rows('publications').filter(p => p.active).length} note={plural(rows('releases').length, 'versión registrada', 'versiones registradas')} icon="cloud" tone="amber" />
                <MetricCard label="Solicitudes de soporte" value={rows('tickets').filter(t => t.status !== 'closed').length} note="Con consentimiento del restaurante" icon="help" tone="green" />
            </Kpis>
            <section className="card panel"><PanelHeading title="Restaurantes" note="Cada restaurante, a su ritmo" icon="store" /><DataTable columns={['Restaurante', 'Sitio', 'Plan', 'Estado', '']} rows={restaurants.map(r => [<b>{r.name}</b>, <code>{r.siteId}</code>, plan(r.planId), <StatusBadge value={r.status} label={r.status === 'active' ? 'Activo' : r.status === 'suspended' ? 'Suspendido' : undefined} />, <span style={{ display: 'flex', gap: 6, justifyContent: 'flex-end', flexWrap: 'wrap' }}><Button className="ghost xs" icon="edit" onClick={() => edit(r)}>Administrar</Button><Button className="ghost xs" icon="plus" onClick={() => form('Otra sucursal', [field('name', 'Nombre'), field('siteId', 'Identidad del servidor'), field('clientCertificateSha256', 'Huella mTLS')], 'owner.branch', { restaurantId: r.id })}>Registrar sucursal</Button><Button className="ghost xs" icon="key" onClick={() => invoke('owner.entitlement', { id: r.id })}>Contratación firmada</Button></span>])} empty="Registra el primer restaurante." />{json}</section></>;

    }
    if (page === 'modules') return <>
        <PageTools><Button className="primary" icon="plus" onClick={() => form('Plan comercial', [field('name', 'Nombre'), field('maxUsers', 'Usuarios', 'number', 15), field('maxTables', 'Mesas', 'number', 30), field('maxBranches', 'Sucursales', 'number', 1)], 'owner.plan')}>Plan</Button></PageTools>
        <section className="card panel"><PanelHeading title="Planes comerciales" icon="layers" /><DataTable columns={['Plan', '>Usuarios', '>Mesas', '>Sucursales', '>Restaurantes']} rows={rows('plans').map(p => [<b>{p.name}</b>, p.maxUsers, p.maxTables, p.maxBranches, rows('restaurants').filter(r => r.planId === p.id).length])} /></section>
        <div className="g g3 stagger">{rows('restaurants').map(r => <section className="card panel" key={r.id}><PanelHeading title={r.name} note={(r.modules || []).length + ' de ' + Object.keys(MODULES).length + ' módulos'} icon="store" action={<Button className="ghost xs" icon="settings" onClick={() => form('Módulos contratados', [field('modules', 'Módulos', 'multi', r.modules, choice(s.modules || Object.keys(MODULES)))], 'owner.modules', { id: r.id })}>Configurar módulos</Button>} /><div className="chips">{Object.entries(MODULES).map(([k, v]) => <span className={'tag ' + ((r.modules || []).includes(k) ? 'on' : 'off')} key={k}>{(r.modules || []).includes(k) ? '✓ ' : ''}{v}</span>)}</div></section>)}</div></>;
    if (page === 'commercial') return <div className="g g3 stagger">{rows('restaurants').map(r => <section className="card panel" key={r.id}><PanelHeading title={r.name} note={(r.commercial?.mode || '—') + ' · Precio por confirmar'} icon="key" />{SERVICES.map(([k, label]) => { const until = r.commercial?.[k], left = until ? (Date.parse(until) - Date.now()) / 86400000 : 0; return <div key={k} style={{ marginTop: 12 }}><div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12.5 }}><span style={{ color: 'var(--muted)' }}>{label}</span><b className="num" style={{ color: 'var(--ink)' }}>{until ? (left < 0 ? 'Vencido ' + new Date(until).toLocaleDateString('es-MX', { day: 'numeric', month: 'short' }) : new Date(until).toLocaleDateString('es-MX', { day: 'numeric', month: 'short', year: 'numeric' })) : 'No aplica'}</b></div><div style={{ marginTop: 6 }}><Bar value={Math.max(0, Math.min(365, left))} max={365} tone={left < 30 ? 'r' : left > 180 ? 'g' : ''} /></div></div>; })}<div style={{ marginTop: 16 }}><Button className="ghost sm wide" icon="settings" onClick={() => form('Coberturas separadas', [field('service', 'Servicio', 'select', 'support', choice(['usage', 'hosting', 'support', 'maintenance', 'updates', 'resale'])), field('until', 'Vigencia ISO 8601 con zona', 'text', new Date(Date.now() + 31536000000).toISOString()), flag('enabled', 'Habilitado', true)], 'owner.service', { id: r.id })}>Configurar servicio</Button></div></section>)}{!rows('restaurants').length && <Empty title="Sin restaurantes" text="Registra un restaurante en el portafolio." />}</div>;
    if (page === 'backups') return <>
        <PageTools><Button className="primary" icon="db" onClick={() => invoke('owner.backup', {})}>Crear respaldo</Button></PageTools>
        <section className="card panel"><PanelHeading title="Respaldos cifrados" note={rows('backups').length ? 'Último: ' + date(rows('backups').at(-1)!.at) : 'Aún no hay respaldos'} icon="db" /><DataTable columns={['Fecha', '>Tamaño', 'Integridad SHA-256', '']} rows={rows('backups').slice().reverse().map(b => [date(b.at), (b.bytes / 1048576).toFixed(1) + ' MB', <code>{String(b.sha256).slice(0, 4) + '…' + String(b.sha256).slice(-4)}</code>, <Button className="ghost xs" icon="download" onClick={() => run(() => native('file.exportBackup', { id: b.id, sha256: b.sha256 }))}>Exportar respaldo cifrado…</Button>])} />{json}</section></>;
    if (page === 'releases') return <>
        <PageTools><Button className="ghost" icon="upload" onClick={() => run(async () => setResult(await native('file.uploadPackage')))}>Cargar paquete…</Button><Button className="ghost" icon="file" onClick={() => form('Registrar release firmado', [field('filename', 'Archivo cargado', 'text', result?.filename || ''), field('version', 'Versión semántica', 'text', '0.3.0'), field('platform', 'Plataforma', 'select', 'win-x64', choice(['win-x64', 'linux-x64', 'android-arm64'])), field('description', 'Descripción'), field('changes', 'Cambios', 'textarea')], 'owner.release')}>Registrar release</Button><Button className="primary" icon="cloud" onClick={() => form('Publicar selectivamente', [field('releaseId', 'Release', 'select', '', opts('releases')), field('restaurantIds', 'Destinatarios', 'multi', [], opts('restaurants'))], 'owner.publish')}>Publicar selectivamente</Button></PageTools>
        <Notice tone="info">Manifiesto firmado RSA-PSS y destinatarios explícitos. Los instaladores requieren su firma de distribución.</Notice>
        <div className="g g2"><section className="card panel"><PanelHeading title="Versiones" icon="cloud" /><DataTable columns={['Versión', 'Plataforma', 'Descripción', 'Cambios']} rows={rows('releases').map(r => [<b>{r.manifest?.version}</b>, r.manifest?.platform, r.description, r.changes])} /></section>
            <section className="card panel"><PanelHeading title="Publicaciones" note="Quién recibe cada versión" icon="upload" /><DataTable columns={['Publicación', 'Estado', 'Destinatarios', '']} rows={rows('publications').map(p => [<code>{p.id.slice(0, 8)}</code>, <StatusBadge value={p.active ? 'active' : 'revoked'} label={p.active ? 'Activa' : 'Retirada'} />, (p.restaurantIds || []).map((id: string) => rows('restaurants').find(r => r.id === id)?.name || id).join(', '), p.active && <Button className="ghost xs" icon="close" onClick={() => invoke('owner.withdraw', { id: p.id })}>Retirar</Button>])} /></section></div>{json}</>;
    if (page === 'support') return <div className="g g2 stagger">{!rows('tickets').length && <section className="card panel"><Empty icon="message" title="Sin solicitudes de soporte" text="Las solicitudes de las sucursales aparecerán aquí." /></section>}{rows('tickets').map(t => <section className="card panel" key={t.id}><PanelHeading title={t.siteId + ' · ' + t.subject} note={date(t.at)} icon="message" action={<StatusBadge value={t.status || 'open'} />} /><div className="rows">{(t.messages || []).map((m: any, i: number) => <div className="r" key={i}><div className="w"><b>{m.name}</b><span style={{ whiteSpace: 'normal', color: 'var(--text)' }}>{m.message}</span></div></div>)}</div><div style={{ marginTop: 14 }}><Button className="primary sm" icon="message" onClick={() => form('Respuesta a la sucursal', [field('message', 'Mensaje', 'textarea')], 'owner.ticket.reply', { id: t.id })}>Responder</Button></div></section>)}</div>;
    if (page === 'audit') return <section className="card panel"><PanelHeading title="Operaciones" note="Historial del proveedor" icon="history" /><DataTable columns={['Fecha', 'Responsable', 'Operación']} rows={rows('audit').slice().reverse().map(a => [date(a.at), a.actor, a.operation || a.type])} /></section>;
    return null;

}
